import {travelProfile} from './travel-editor.js';
const STOCK='3d0c79f1627022e18765766f6cb5ea067f6b5bf7dca115552189ad65a5c3a8ac';
export function readGameRules(reader,hash){travelProfile(hash);const obedience=hash===STOCK?0x1d492:0x206ee;for(const [i,n]of [10,30,50,70].entries())if(reader.u16(obedience+i*14)!==(0x2600|n))throw Error('The native obedience thresholds failed verification.');const money=hash===STOCK?0x54b60:null;if(money!==null&&reader.u32(money)!==3000)throw Error('The starting-money literal failed verification.');return{obedience,money,levels:[10,30,50,70],startingMoney:money===null?null:3000};}
export function validateGameRules(r){if(r===undefined)return;if(!r||!Array.isArray(r.obedience)||r.obedience.length!==4||r.obedience.some((n,i)=>!Number.isInteger(n)||n<1||n>100||i&&n<r.obedience[i-1])||r.startingMoney!==undefined&&(!Number.isInteger(r.startingMoney)||r.startingMoney<0||r.startingMoney>999999))throw Error('Use four increasing obedience levels from 1 to 100 and starting money from 0 to 999999.');}
export function installGameRules(project,reader,hash,output){const r=project.travelEdits?.[hash]?.rules;if(!r)return[];validateGameRules(r);const p=readGameRules(reader,hash),reports=[];r.obedience.forEach((n,i)=>output.write(p.obedience+i*14,Uint8Array.of(n)));reports.push('Traded Pokémon obedience: '+r.obedience.join(' / '));if(r.startingMoney!==undefined){if(p.money===null)throw Error('Starting money is not a patchable literal in this verified source profile. Leave it at native settings.');output.int(p.money,r.startingMoney);reports.push('New-game starting money: '+r.startingMoney);}return reports;}
export function gameRulesWorkshop(api){const $=s=>document.querySelector(s),esc=api.esc;function open(){const session=api.session();if(!session)throw Error('Open the original ROM first.');const hash=session.id,native=readGameRules(session.reader,hash),old=api.project().travelEdits?.[hash]?.rules,levels=old?.obedience||native.levels;api.modal('Global game rules',`<p>Set the level at which traded Pokémon obey for each badge milestone. Set every threshold to 100 to remove that level restriction. Native ownership and story checks remain active.</p>${[0,2,4,6].map((badges,i)=>`<label>${badges} badges<input id="obeyLevel${i}" type="number" min="1" max="100" value="${levels[i]}"></label>`).join('')}<button id="gameRulesObeyAll" type="button">All traded Pokémon obey</button>${native.money!==null?`<label>Starting money for new games<input id="gameRulesMoney" type="number" min="0" max="999999" value="${old?.startingMoney??native.startingMoney}"></label>`:''}<button id="gameRulesReset" type="button">Restore native game rules</button>`,()=>{const rules={obedience:[0,1,2,3].map(i=>+$('#obeyLevel'+i).value),...(native.money!==null?{startingMoney:+$('#gameRulesMoney').value}:{})};validateGameRules(rules);api.change(()=>{api.project().travelEdits??={};api.project().travelEdits[hash]??={fly:{},grids:{}};api.project().travelEdits[hash].rules=rules;});api.toast('Global game rules saved to project.');},'Save game rules');$('#gameRulesObeyAll').onclick=()=>[0,1,2,3].forEach(i=>$('#obeyLevel'+i).value=100);$('#gameRulesReset').onclick=()=>{api.change(()=>{if(api.project().travelEdits?.[hash])delete api.project().travelEdits[hash].rules;});open();};}return{open};}
